\-- DACA Week 4: SQL Aggregation (Role A: Sales Summary) -- Author: Onur -- Stakeholders: Kristi Tamm (CEO) &amp; Anna Mets (Marketing Lead) -- Query 1: Monthly Sales Baseline Summary (2024-2025) SELECT date\_trunc('month', sale\_date) AS month, count(sale\_id) AS order\_count, sum(total\_price) AS total\_revenue, round(avg(total\_price), 2) AS average\_order FROM sales WHERE sale\_date &gt;= '2024-01-01' GROUP BY date\_trunc('month', sale\_date) ORDER BY month; -- Query 2: Revenue &amp; Orders by Product Category (&gt; 5,000 EUR) SELECT p.category, count(DISTINCT p.product\_id) AS product\_count, count(s.sale\_id) AS total\_orders, sum(s.total\_price) AS total\_revenue, round(avg(s.total\_price), 2) AS average\_price FROM sales s JOIN products p ON s.product\_id = p.product\_id GROUP BY p.category HAVING sum(s.total\_price) &gt; 5000 ORDER BY total\_revenue DESC; -- Query 3: Month-on-Month Revenue Trend &amp; Growth Rate (CTE &amp; LAG) WITH monthly\_sales AS ( SELECT date\_trunc('month', sale\_date) AS month, sum(total\_price) AS revenue FROM sales WHERE sale\_date &gt;= '2024-01-01' GROUP BY date\_trunc('month', sale\_date) ) SELECT month, revenue, lag(revenue) OVER (ORDER BY month) AS previous\_month\_revenue, revenue - lag(revenue) OVER (ORDER BY month) AS revenue\_change, round((revenue - lag(revenue) OVER (ORDER BY month)) / nullif(lag(revenue) OVER (ORDER BY month), 0) \* 100, 1) AS growth\_percentage FROM monthly\_sales ORDER BY month;
